    const syn = (Array.isArray(e.sinonimos) && e.sinonimos.length > 0) ? (' [Sinónimos: ' + e.sinonimos.join(', ') + ']') : '';
    const notes = e.notas ? (' | Notas: ' + e.notas) : '';
    const costNum = Number(e.costo_usd) || 0;
    return '• ' + e.nombre_examen + syn + ' (' + (e.categoria || 'General') + '): $' + costNum.toFixed(2) + ' USD | Muestra: ' + (e.tipo_muestra || 'Sangre') + ' | Requisitos: ' + (e.requisitos_preanaliticos || 'Ayuno habitual') + notes;
  }).join('\n');
}

const botActive = (leadStatus !== 'ESCALADO_HUMANO' && leadStatus !== 'FINALIZADO');

if (!botActive) {
